72	    const FIX_AVAILABILITY: FixAvailability = FixAvailability::Sometimes;
73	
74	    #[derive_message_formats]
75	    fn message(&self) -> String {
76	        "FastAPI dependency without `Annotated`".to_string()
77	    }
